package com.scoop.app.core.sound

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import android.os.SystemClock
import androidx.annotation.RawRes
import com.scoop.app.R
import com.scoop.app.util.PrefKeys
import com.scoop.app.util.PreferenceUtil
import java.util.concurrent.ConcurrentHashMap

/** Short feedback sounds for in-app moments. Generated by android/scripts/generate_ui_sounds.py. */
enum class UiSound(@RawRes val resId: Int) {
    DOWNLOAD_COMPLETE(R.raw.sound_download_complete),
    DOWNLOAD_FAILED(R.raw.sound_download_failed),
    DELETE(R.raw.sound_delete),
    UNDO(R.raw.sound_undo),
}

/** Tracks whether Scoop's (single) activity is on screen, so sounds never play from the
 * background - the "Download complete" notification already covers that case. */
object AppVisibility {
    @Volatile private var startedActivities = 0

    val isForeground: Boolean get() = startedActivities > 0

    fun onActivityStarted() { startedActivities++ }

    fun onActivityStopped() { startedActivities = (startedActivities - 1).coerceAtLeast(0) }
}

/**
 * Plays quiet UI sounds through [SoundPool], which is built for short, low-latency effects.
 * A sound is skipped when the user turned sounds off, the phone is on silent or vibrate, Scoop
 * isn't visible, or the same sound just played (so a burst of finished images gives one chime).
 */
class UiSounds(private val context: Context) {
    private val soundPool =
        SoundPool.Builder()
            .setMaxStreams(2)
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                    .build(),
            )
            .build()
    private val soundIds = ConcurrentHashMap<UiSound, Int>()
    private val loadedIds = ConcurrentHashMap.newKeySet<Int>()
    private val lastPlayedAt = ConcurrentHashMap<UiSound, Long>()

    init {
        soundPool.setOnLoadCompleteListener { _, soundId, status -> if (status == 0) loadedIds += soundId }
        UiSound.entries.forEach { soundIds[it] = soundPool.load(context, it.resId, 1) }
    }

    val enabled: Boolean get() = PreferenceUtil.getBoolean(PrefKeys.UI_SOUNDS, true)

    fun play(sound: UiSound) {
        if (!enabled || !AppVisibility.isForeground) return
        val audioManager = context.getSystemService(AudioManager::class.java)
        if (audioManager?.ringerMode != AudioManager.RINGER_MODE_NORMAL) return
        val now = SystemClock.elapsedRealtime()
        val previous = lastPlayedAt.put(sound, now)
        if (previous != null && now - previous < MIN_REPEAT_GAP_MS) return
        val soundId = soundIds[sound]?.takeIf { it in loadedIds } ?: return
        soundPool.play(soundId, VOLUME, VOLUME, 1, 0, 1f)
    }

    private companion object {
        const val VOLUME = 0.6f
        const val MIN_REPEAT_GAP_MS = 700L
    }
}
